SELECT uuid, toTimeZone(timestamp, 'UTC') AS captured_at_utc, toTimeZone(created_at, 'UTC') AS ingested_at_utc, properties.collector_source AS collector_source, properties.collection_scope AS collection_scope, properties.environment AS environment, properties.latest_hour_bytes AS latest_hour_bytes, properties.latest_hour_start AS latest_hour_start, properties.latest_hour_end AS latest_hour_end, properties.provider_healthy AS provider_healthy, properties.collection_healthy AS collection_healthy FROM events WHERE event = 'mikka_ops_snapshot' AND timestamp >= toDateTime('2026-11-04 18:00:00', 'UTC') AND timestamp < toDateTime('2026-11-04 21:00:00', 'UTC') ORDER BY timestamp LIMIT 30
